prop_re=re.compile(r'Received proposal: Block\{ hash: (\S+) parent: (\S+), proposer: ([0-9]+), view: ([0-9]+) , cert: QC\{ hash: (\S+), view: ([0-9]+), IDs: \[ (.*?) \] \}')
vote_re=re.compile(r'\b(hs[1-4])\s+votingmachine/votingmachine\.go:55\s+CollectVote\(from ([1-4])\): (\S+)')
advqc_re=re.compile(r'advanceView: \{ QC\{ hash: (\S+), view: ([0-9]+), IDs: \[ (.*?) \] \}')
block_re=re.compile(r'Block\{ hash: (\S+) parent: (\S+), proposer: ([0-9]+), view: ([0-9]+) , cert: QC\{ hash: (\S+), view: ([0-9]+), IDs: \[ (.*?) \] \}')
for name,path in files.items():
 proposals=[];receives=collections.Counter();byhash=collections.defaultdict(list);votes=collections.defaultdict(list);advs=[];events=[];newview=collections.Counter();counts=collections.Counter();commit_events=[];badvotes=[];qcprocess=[]
 with open(path,errors='replace') as f:
  for lineno,line in enumerate(f,1):
   if 'Received proposal: Block{' in line:
    m=prop_re.search(line)
    if m:
     h,parent,proposer,view,chash,qview,ids=m.groups();item=dict(line=lineno,rep=line.split('\t')[2],hash=h,parent=parent,prop=int(proposer),view=int(view),chash=chash,qview=int(qview),ids=[int(x) for x in ids.split()] if ids.strip() else [])
     proposals.append(item);receives[item['rep']]+=1;byhash[h].append(item);events.append((lineno,'proposal',item['rep'],h,item))
     if h not in [x['hash'] for x in proposals[:-1]]: pass
   m=vote_re.search(line)
   if m:
    r,s,h=m.groups();votes[(r,h)].append((lineno,int(s)));events.append((lineno,'vote',r,h,int(s)))
   m=advqc_re.search(line)
   if m:
    h,v,ids=m.groups();qcprocess.append((lineno,line.split('\t')[2],h,int(v),[int(x) for x in ids.split()] if ids.strip() else []))
   for key in ['advanceView: Successfully updated HighQC','advanceView: HighQC not updated','advanceView: Advanced to view','OnNewView (from network: false)','OnNewView (from network: true)','OnRemoteTimeout (advancing view)','OnRemoteTimeout (second advance)','not enough timeouts','OnLocalTimeout:','failed to verify incoming vote','Failed to verify sync info','block too old','CommitRule - PRE_COMMIT','CommitRule - COMMIT','CommitRule - DECIDE']:
    if key in line:counts[key]+=1
   if 'OnNewView (' in line:
    m=re.search(r'OnNewView \(from network: (true|false)\)',line)
    if m:newview[m.group(1)]+=1
   if 'failed to verify incoming vote' in line or 'Failed to verify sync info' in line:badvotes.append((lineno,line.rstrip()))
   if any(x in line for x in ('CommitRule - PRE_COMMIT','CommitRule - COMMIT','CommitRule - DECIDE')):
    m=block_re.search(line)
    if m:commit_events.append((lineno,line.split('\t')[2],line.split('\t')[-1].split(':')[0],m.groups()))
 # relation valid proposal cert
 rel=collections.Counter();mism=[]
 blockviews={x['hash']:x['view'] for x in proposals}
 for p in proposals:
  rel['proposal lines']+=1
  rel['parent_is_cert_hash']+=p['parent']==p['chash']
  rel['qc_view_is_v_minus_1']+=p['qview']==p['view']-1
  if p['parent'] in blockviews and blockviews[p['parent']]==p['view']-1: rel['parent_block_view_vminus1']+=1
  if p['qview']>0 and len(p['ids'])>=3 and len(set(p['ids']))==len(p['ids']):rel['qc_has_three_plus_distinct_ids']+=1
  if p['parent']!=p['chash'] or p['qview']!=p['view']-1: mism.append(p)
 # child proposal linking prior parent's QC
 childlink=collections.Counter(); linkexamples=[]
 for p in proposals:
  parentproposals=byhash.get(p['chash'],[])
  if parentproposals and parentproposals[0]['view']==p['view']-1:
   childlink['child_qc_certifies_parent_block_prev_view']+=1
   if p['qview']==p['view']-1:childlink['both']+=1
 # per collector proposal received, QC processed, own vote same hash ordering
 order=collections.Counter(); examples={}
 for p in proposals:
  r=p['rep'];h=p['hash']; own=[ln for ln,s in votes.get((r,h),[]) if s==int(r[-1])]
  if own:
   order['proposal_and_own_vote']+=1
   qcs=[q for q in qcprocess if q[1]==r and q[2]==p['chash'] and q[3]==p['qview']]
   if qcs:
    order['matching_parent_qc_processed']+=1
    if p['line']<qcs[0][0]<own[0]:order['proposal_qc_vote_order']+=1
    elif qcs[0][0]<p['line']<own[0]:order['qc_before_proposal_then_vote']+=1
    elif p['line']<own[0]:order['proposal_vote_no_intervening_qc_log']+=1
    if p['view'] in (1,2,3) and r not in examples:examples[r]=(p,qcs[0][0],own[0])
 # vote grouping statistics; events with vote lines and qualifying full distinct sender sets
 vg=collections.Counter(); exvotes=[]
 for (r,h),items in votes.items():
  senders=[s for ln,s in items]; vg['groups']+=1;vg['lines']+=len(items)
  if len(senders)>=3:vg['at_least3_entries']+=1
  if len(set(senders))>=3:vg['at_least3_distinct_senders']+=1
  if len(senders)==4 and len(set(senders))==4:vg['exactly_four_distinct']+=1
 # QC formed evidence future child cert: count view-v proposals that get child proposal view+1 in log
 child_by_parent=collections.Counter()
 for p in proposals:
  if p['view']>0:
   for child in proposals:
    if child['view']==p['view']+1 and child['parent']==p['hash'] and child['chash']==p['hash'] and child['qview']==p['view']:
     child_by_parent[p['hash']]+=1
 # Print
 print('\n',name,'proposal n',len(proposals),'receives',dict(sorted(receives.items())),'unique blocks',len(byhash))
 print('proposal relation',dict(rel),'mismatches',len(mism),'block views known',len(blockviews),'child QCs',len(child_by_parent),'childlinks count',dict(childlink))
 print('vote groups',dict(vg),'newview',dict(newview),'other counts',dict(counts))
 print('order',dict(order),'examples')
 for r,x in examples.items():print(' ',r,'proposal line',x[0]['line'],'v',x[0]['view'],'hash',x[0]['hash'],'parent',x[0]['parent'],'QC',x[0]['qview'],x[0]['ids'],'qc_process_line',x[1],'own_vote_line',x[2])
 print('first newview events')
 # first block / proposal events and relevant line range 55-125 for run1
 if name=='run1':
  for no,line in enumerate(open(path,errors='replace'),1):
   if 55<=no<=135 and any(x in line for x in ('Received proposal','advanceView: {','HighQC','Advanced to view','VoteRule','CollectVote','OnNewView','CommitRule - COMMIT','CommitRule - DECIDE','CommitRule - PRE_COMMIT','TryCommit')):print(no,line.rstrip())
 # commit examples first events
 print('commit examples',[(ln,rep,kind,g[0],g[3]) for ln,rep,kind,g in commit_events[:4]])
